export default {"id": "05", "title": "树给横坐标，轮廓线给高度", "outline": [10, 8], "catalog": {"A": [3, 2], "B": [2, 3], "C": [2, 2], "D": [3, 1], "E": [2, 2]}, "scenes": [{"key": "intro-why", "chapter": 1, "title": "切片表达式写不出的布局，怎么办？", "view": "intro-why05", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 18, "note": "Lab4结尾：6×4见证没有第一刀；需要更强的表示法", "say": "上一课的结尾留了一个问题：最紧的6×4摆法没有第一刀，切片表达式写不出来。要表达更多布局，就要放弃“每一刀都贯穿到底”的限制。B*-tree 只要求每个模块记住两个邻居关系，其余交给轮廓线。它能表达这五块在10×8里的全部5040种树形摆法。", "start": 0, "delivery": "reading", "end": 21.17}, {"key": "intro-task", "chapter": 1, "title": "本课任务：树加轮廓线，完成打包", "view": "intro-goal05", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 18, "note": "先序遍历+整个区间的轮廓查询+残段保留", "say": "本课的任务是完成完整打包：按先序遍历树，左孩子接父块右边缘、右孩子与父块同 x；每个模块落到自己整个覆盖区间下最高的轮廓线上。学完你能解释任何一个落点为什么在那里，也能说清树编辑会连累哪些模块。", "start": 21.17, "delivery": "reading", "end": 39.17}, {"key": "intro-preview", "chapter": 1, "title": "还是那五块，先认识标准树", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "标准树 A(B(C(E,-),-),D) 的解码结果又是9×3", "say": "标准树写作 A(B(C(E,-),-),D)：A 是根，B 是 A 的左孩子，C 挂在 B 下面，E 挂在 C 下面，D 是 A 的右孩子。它解码出来还是那张9×3的标准布局。老朋友，新来路。", "start": 39.17, "delivery": "reading", "end": 56.17}, {"key": "convention", "chapter": 2, "title": "两个约定：x 由树决定", "view": "convention-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "recipe", "note": "左孩子接父块右边缘；右孩子与父块同 x；y 都由轮廓决定", "start": 56.17, "delivery": "voice", "end": 63.22}, {"key": "preorder", "chapter": 2, "title": "先序遍历：整个左子树在前", "view": "preorder-order", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "root", "note": "标准树摆放松序：A、B、C、E、D", "start": 63.22, "delivery": "voice", "end": 69.358}, {"key": "order-matters", "chapter": 2, "title": "顺序反了，结果就变了", "view": "order-matters", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "同一棵树：先右孩子再左子树，轮廓完全不同", "say": "为什么强调“整个左子树在前”？把顺序反过来试一次：根摆好后先放右孩子 D，再回头放左子树。D 看到的轮廓和正确顺序完全不同，后面每一块跟着变。对标准树这恰好还是合法的，但布局已经不一样；换一棵树甚至会出现重叠。顺序是算法的一部分。", "start": 69.358, "delivery": "reading", "end": 89.528}, {"key": "golden-walk", "chapter": 3, "title": "逐步摆放：A、B、C、E", "view": "walk", "step": 3, "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "walk", "note": "树与布图同时高亮当前模块；轮廓线逐段更新", "start": 89.528, "delivery": "voice", "end": 98.09}, {"key": "d-landing", "chapter": 3, "title": "D 落在哪里？看整个区间", "view": "walk", "step": 5, "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "D", "note": "D 查询 [0,3)：最高是 A 的顶部2，不是某个单点", "question": {"prompt": "D 的覆盖区间是 [0,3)。如果这个区间里同时有高2和高3的两段轮廓，D 落在哪？", "choices": ["y=3：取整个区间的最大值", "y=2：跟父块顶边走", "y=0：有空隙就落地"], "answer": 0, "replies": ["轮廓查询取覆盖区间内所有段的最大值。", "跟父块顶边是本课要排除的错误实现。", "轮廓没有空隙的概念：段的高度就是已占用高度。"]}, "start": 98.09, "delivery": "voice", "end": 106.1}, {"key": "contour-update", "chapter": 3, "title": "放块之后，轮廓怎么改", "view": "contour-update", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "D 放下后 [0,3) 从2升到3；[3,5)=3与它相邻等高→合并", "say": "放块的更新分三步：把旧区间里被盖住的部分切开，整段换成新的高度，再把相邻等高的段合并。标准树最后一步，D 把 [0,3) 从2抬到3，它与相邻的 [3,5)=3 等高，合并成 [0,5)=3。", "start": 106.1, "delivery": "reading", "end": 123.1}, {"key": "swap-predict", "chapter": 4, "title": "交换名称：D 还停在高度2吗？", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "predict", "note": "树 C(B(A(E,-),-),D)：先想一想再往下看", "start": 123.1, "delivery": "voice", "end": 129.816}, {"key": "lift-result", "chapter": 4, "title": "D 被托到高度3", "view": "board", "rows": [["A", 4, 0, 3, 2], ["B", 2, 0, 2, 3], ["C", 0, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "voice": "lift", "note": "D 与根同 x，但覆盖区间跨到了高3的B上", "start": 129.816, "delivery": "voice", "end": 137.778}, {"key": "lift-anatomy", "chapter": 4, "title": "托住 D 的是哪一段？", "view": "lift-anatomy", "rows": [["A", 4, 0, 3, 2], ["B", 2, 0, 2, 3], ["C", 0, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "查询[0,3)：C顶2、B顶3，取最大3；不是父块顶边的2", "say": "把 D 的查询区间画出来：它覆盖 x 从0到3，这一段里有两段轮廓——C 的顶部2和B的顶部3。取最大，D 落在3。“右孩子坐在父块上”只是标准树里的巧合，不是算法。只看父块顶边的程序，在这里会写错。", "start": 137.778, "delivery": "reading", "end": 155.448}, {"key": "segments", "chapter": 5, "title": "查询是整段区间，不是单点", "view": "segments", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "B 查询 [3,5)：区间里哪怕一段很高也托得动", "say": "轮廓查询有两个要点：一是覆盖整个 [x,x+w)，宽块要跨过好几段；二是只看有正长度的重叠，边界相接不算。只查一个点或只查父块，都会漏掉别处的高的段。", "start": 155.448, "delivery": "reading", "end": 168.948}, {"key": "residual-detail", "chapter": 5, "title": "残段：被切开后剩下的尾巴", "view": "residual-detail", "rows": [["A", 0, 0, 3, 2], ["B", 5, 1, 2, 3], ["C", 3, 1, 2, 2], ["D", 3, 0, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 15, "note": "D占[3,6)；C只盖[3,5)，残段[5,6)=1托住了B", "say": "看这棵树：D 先占 [3,6) 高1；C 作为 D 的右孩子落在 x=3、宽2，只盖住 [3,5)，把 [5,6) 留成高1的残段。后来 B 的查询区间 [5,7) 里最高的就是这段残段，所以 B 落在 y=1。如果程序把 [3,6) 整段删掉重写，残段丢失，B 会落到 y=0，和 D 重叠。", "start": 168.948, "delivery": "reading", "end": 194.448}, {"key": "neighborhoods", "chapter": 6, "title": "两类编辑，两种影响", "view": "neighborhood-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "换名称只动名字；移动节点会连累整棵子树", "say": "树的编辑有两类。交换两个名称：树形不变，每个模块的宽高换了位置，谁被托高要看新宽高。移动一个节点：它和整棵子树都要重摆，后面的轮廓也跟着变。这两类正是以后搜索的邻域；现在先学会判断“谁需要重摆”。", "start": 194.448, "delivery": "reading", "end": 211.778}, {"key": "pre-checks", "chapter": 6, "title": "解码前，先把树查一遍", "view": "checks-cards05", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 12, "note": "未知、重复、缺失先拒绝；树形合法仍可能越界", "say": "和上一课一样，解码前先查名称：树里不能出现清单之外的模块，不能重复，也不能缺失。轮廓算法保证摆出来的块互不重叠，但它不管外框：5040棵树里有360棵越界。合法性要靠Lab2的检查器。", "start": 211.778, "delivery": "reading", "end": 228.108}, {"key": "enum-facts", "chapter": 7, "title": "5040、4680、24：三个数字的来历", "view": "enum-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 15, "note": "42形状×120标号=5040；4680棵装进10×8；最小面积24", "say": "本机穷举可以核对：5个节点42种形状，乘120种标号，共5040棵树；其中4680棵完整放进10×8，越界的360棵全部没有内部重叠；最小包围盒面积24，只有8棵达到。轮廓算法保证不重叠，但不保证面积小。", "start": 228.108, "delivery": "reading", "end": 246.108}, {"key": "enum-bound", "chapter": 7, "title": "这些数字只属于这组数据", "view": "enum-bound", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "换模块清单或外框，一切重新枚举；穷举只在显式按钮下做", "say": "要提醒边界：5040、4680、24只属于当前五块、固定尺寸、禁止旋转和10×8外框。模块清单一变，数字全部作废。穷举只在页面提供的小规模按钮下做，不会在后台持续运行。", "start": 246.108, "delivery": "reading", "end": 261.108}, {"key": "score-compare", "chapter": 8, "title": "合法了，但更好吗？", "view": "score-compare", "rows": [["A", 4, 0, 3, 2], ["B", 2, 0, 2, 3], ["C", 0, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "from": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "score", "note": "27变36；谁更好要回到Lab3的评价与分母", "start": 261.108, "delivery": "voice", "end": 268.83}, {"key": "transfer", "chapter": 8, "title": "轮到你：算托高、修轮廓、编辑树", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "counterexample", "note": "三项实验在下方Lab区；树编辑用同一套写法", "start": 268.83, "delivery": "voice", "end": 277.104}], "chapters": ["为什么还需要一棵树", "约定与先序遍历", "标准树逐步摆放", "预测与托高", "轮廓更新的细节", "两类邻域与检查", "穷举的边界", "轮到你解释落点"], "duration": 277.104, "readingSeconds": 216.67, "captions": [{"start": 0, "end": 6.473471074380166, "text": "上一课的结尾留了一个问题：最紧的6×4摆法没有第一刀，切片表达式写不出来。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 6.473471074380166, "end": 11.022396694214876, "text": "要表达更多布局，就要放弃“每一刀都贯穿到底”的限制。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 11.022396694214876, "end": 16.62107438016529, "text": "B*-tree 只要求每个模块记住两个邻居关系，其余交给轮廓线。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 16.62107438016529, "end": 21.17, "text": "它能表达这五块在10×8里的全部5040种树形摆法。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 21.17, "end": 32.86072164948454, "text": "本课的任务是完成完整打包：按先序遍历树，左孩子接父块右边缘、右孩子与父块同 x；每个模块落到自己整个覆盖区间下最高的轮廓线上。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 32.86072164948454, "end": 39.17, "text": "学完你能解释任何一个落点为什么在那里，也能说清树编辑会连累哪些模块。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 39.17, "end": 51.56583333333334, "text": "标准树写作 A(B(C(E,-),-),D)：A 是根，B 是 A 的左孩子，C 挂在 B 下面，E 挂在 C 下面，D 是 A 的右孩子。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 51.56583333333334, "end": 54.75333333333334, "text": "它解码出来还是那张9×3的标准布局。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 54.75333333333334, "end": 56.17, "text": "老朋友，新来路。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 56.17, "end": 63.22, "text": "树给出摆放关系，轮廓线决定每块模块最终落下的高度。", "delivery": "voice", "sourceKey": "recipe", "words": [{"text": "树", "start": 56.272083, "end": 56.558541000000005}, {"text": "给出", "start": 56.558541000000005, "end": 56.858041}, {"text": "摆放", "start": 56.884083000000004, "end": 57.196583000000004}, {"text": "关系", "start": 57.209583, "end": 57.730416000000005}, {"text": "轮廓线", "start": 58.095, "end": 58.772083}, {"text": "决定", "start": 58.785125, "end": 59.058583}, {"text": "每", "start": 59.084583, "end": 59.227833000000004}, {"text": "块", "start": 59.227833000000004, "end": 59.397124000000005}, {"text": "模块", "start": 59.410125, "end": 59.917958}, {"text": "最终", "start": 60.035125, "end": 60.503875}, {"text": "落下", "start": 60.516875, "end": 60.803333}, {"text": "的", "start": 60.803333, "end": 60.868458000000004}, {"text": "高度", "start": 60.881458, "end": 61.246041000000005}]}, {"start": 63.22, "end": 69.358, "text": "先让根模块 A 落在原点，然后处理它的整个左子树。", "delivery": "voice", "sourceKey": "root", "words": [{"text": "先", "start": 63.322083000000006, "end": 63.556458000000006}, {"text": "让", "start": 63.556458000000006, "end": 63.699708}, {"text": "根模", "start": 63.725750000000005, "end": 64.012208}, {"text": "块", "start": 64.012208, "end": 64.35074900000001}, {"text": "A", "start": 64.454916, "end": 64.637207}, {"text": "落", "start": 64.637208, "end": 64.780416}, {"text": "在", "start": 64.780416, "end": 64.858541}, {"text": "原点", "start": 64.871583, "end": 65.379416}, {"text": "然后", "start": 65.717916, "end": 66.043457}, {"text": "处理", "start": 66.056458, "end": 66.290833}, {"text": "它", "start": 66.303875, "end": 66.421041}, {"text": "的", "start": 66.421041, "end": 66.512207}, {"text": "整个", "start": 66.53825, "end": 66.85075}, {"text": "左子", "start": 66.86375, "end": 67.137208}, {"text": "树", "start": 67.137208, "end": 67.397624}]}, {"start": 69.358, "end": 71.9888695652174, "text": "为什么强调“整个左子树在前”？", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 71.9888695652174, "end": 77.25060869565218, "text": "把顺序反过来试一次：根摆好后先放右孩子 D，再回头放左子树。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 77.25060869565218, "end": 81.81078260869566, "text": "D 看到的轮廓和正确顺序完全不同，后面每一块跟着变。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 81.81078260869566, "end": 87.77408695652174, "text": "对标准树这恰好还是合法的，但布局已经不一样；换一棵树甚至会出现重叠。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 87.77408695652174, "end": 89.528, "text": "顺序是算法的一部分。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 89.528, "end": 98.09, "text": "左孩子从父模块的右边缘开始，B、C、E 依次落位，D 最后处理。", "delivery": "voice", "sourceKey": "walk", "words": [{"text": "左", "start": 89.630083, "end": 89.890499}, {"text": "孩子", "start": 89.8905, "end": 90.35925}, {"text": "从", "start": 90.38529100000001, "end": 90.632707}, {"text": "父", "start": 90.63270800000001, "end": 90.749916}, {"text": "模块", "start": 90.762916, "end": 91.062374}, {"text": "的", "start": 91.062375, "end": 91.1405}, {"text": "右", "start": 91.16654100000001, "end": 91.374874}, {"text": "边缘", "start": 91.374875, "end": 91.60925}, {"text": "开始", "start": 91.622291, "end": 92.143124}, {"text": "B", "start": 92.468625, "end": 92.72904100000001}, {"text": "C", "start": 93.106666, "end": 93.588457}, {"text": "E", "start": 94.005083, "end": 94.187374}, {"text": "依次", "start": 94.200416, "end": 94.460832}, {"text": "落位", "start": 94.473833, "end": 94.877499}, {"text": "D", "start": 95.216041, "end": 95.398332}, {"text": "最后", "start": 95.411333, "end": 95.736874}, {"text": "处理", "start": 95.749875, "end": 96.12750000000001}]}, {"start": 98.09, "end": 106.10000000000001, "text": "标准树里，D 的宽度下方最高处是 A 的顶部，所以高度是二。", "delivery": "voice", "sourceKey": "D", "words": [{"text": "标准", "start": 98.192083, "end": 98.608749}, {"text": "树", "start": 98.60875, "end": 98.83012500000001}, {"text": "里", "start": 98.83012500000001, "end": 99.129625}, {"text": "D", "start": 99.54625, "end": 99.715541}, {"text": "的", "start": 99.715541, "end": 99.84574900000001}, {"text": "宽度", "start": 99.85875, "end": 100.210333}, {"text": "下方", "start": 100.223333, "end": 100.62699900000001}, {"text": "最高", "start": 100.653041, "end": 101.004582}, {"text": "处", "start": 101.004583, "end": 101.33012400000001}, {"text": "是", "start": 101.434291, "end": 101.668666}, {"text": "A", "start": 101.681666, "end": 101.87699900000001}, {"text": "的", "start": 101.87700000000001, "end": 101.968166}, {"text": "顶部", "start": 101.981166, "end": 102.358791}, {"text": "所以", "start": 102.65825000000001, "end": 103.166083}, {"text": "高度", "start": 103.28325000000001, "end": 103.686916}, {"text": "是", "start": 103.699916, "end": 103.869166}, {"text": "二", "start": 103.869166, "end": 104.129582}]}, {"start": 106.10000000000001, "end": 113.71458333333334, "text": "放块的更新分三步：把旧区间里被盖住的部分切开，整段换成新的高度，再把相邻等高的段合并。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 113.71458333333334, "end": 123.10000000000001, "text": "标准树最后一步，D 把 [0,3) 从2抬到3，它与相邻的 [3,5)=3 等高，合并成 [0,5)=3。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 123.10000000000001, "end": 129.816, "text": "如果交换 A 和 C 的名称，D 还会停在高度二吗？", "delivery": "voice", "sourceKey": "predict", "words": [{"text": "如果", "start": 123.202083, "end": 123.48854100000001}, {"text": "交换", "start": 123.501583, "end": 123.970333}, {"text": "A", "start": 123.99637500000001, "end": 124.24375000000002}, {"text": "和", "start": 124.24375000000002, "end": 124.373958}, {"text": "C", "start": 124.38700000000001, "end": 124.595333}, {"text": "的", "start": 124.595333, "end": 124.673458}, {"text": "名称", "start": 124.686458, "end": 125.220333}, {"text": "D", "start": 125.545833, "end": 125.88437400000002}, {"text": "还", "start": 125.897416, "end": 126.157832}, {"text": "会", "start": 126.157833, "end": 126.275041}, {"text": "停", "start": 126.288041, "end": 126.405207}, {"text": "在", "start": 126.405208, "end": 126.50937400000002}, {"text": "高度", "start": 126.53541600000001, "end": 126.795832}, {"text": "二", "start": 126.80887500000001, "end": 126.97812500000002}, {"text": "吗", "start": 126.97812500000002, "end": 127.19950000000001}]}, {"start": 129.816, "end": 137.77800000000002, "text": "看交换后的布局；D 覆盖到了更高的 B，所以它被托到高度三。", "delivery": "voice", "sourceKey": "lift", "words": [{"text": "看", "start": 129.918083, "end": 130.178499}, {"text": "交换", "start": 130.17849999999999, "end": 130.543083}, {"text": "后", "start": 130.543083, "end": 130.660291}, {"text": "的", "start": 130.660291, "end": 130.738416}, {"text": "布局", "start": 130.751416, "end": 131.324332}, {"text": "D", "start": 131.728, "end": 131.910291}, {"text": "覆盖", "start": 131.923291, "end": 132.209749}, {"text": "到", "start": 132.222791, "end": 132.352999}, {"text": "了", "start": 132.353, "end": 132.470208}, {"text": "更", "start": 132.496208, "end": 132.691541}, {"text": "高", "start": 132.691541, "end": 132.886832}, {"text": "的", "start": 132.886833, "end": 133.056124}, {"text": "B", "start": 133.14724999999999, "end": 133.407666}, {"text": "所以", "start": 133.824333, "end": 134.423291}, {"text": "它", "start": 134.527458, "end": 134.774874}, {"text": "被", "start": 134.774875, "end": 134.879041}, {"text": "托", "start": 134.892041, "end": 135.048291}, {"text": "到", "start": 135.048291, "end": 135.165499}, {"text": "高度", "start": 135.191541, "end": 135.491041}, {"text": "三", "start": 135.504041, "end": 135.803541}]}, {"start": 137.77800000000002, "end": 146.25960000000003, "text": "把 D 的查询区间画出来：它覆盖 x 从0到3，这一段里有两段轮廓——C 的顶部2和B的顶部3。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 146.25960000000003, "end": 148.02660000000003, "text": "取最大，D 落在3。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 148.02660000000003, "end": 152.44410000000002, "text": "“右孩子坐在父块上”只是标准树里的巧合，不是算法。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 152.44410000000002, "end": 155.448, "text": "只看父块顶边的程序，在这里会写错。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 155.44800000000004, "end": 164.98800000000003, "text": "轮廓查询有两个要点：一是覆盖整个 [x,x+w)，宽块要跨过好几段；二是只看有正长度的重叠，边界相接不算。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 164.98800000000003, "end": 168.94800000000004, "text": "只查一个点或只查父块，都会漏掉别处的高的段。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 168.94800000000004, "end": 180.39697959183678, "text": "看这棵树：D 先占 [3,6) 高1；C 作为 D 的右孩子落在 x=3、宽2，只盖住 [3,5)，把 [5,6) 留成高1的残段。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 180.39697959183678, "end": 187.33575510204088, "text": "后来 B 的查询区间 [5,7) 里最高的就是这段残段，所以 B 落在 y=1。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 187.33575510204088, "end": 194.44800000000006, "text": "如果程序把 [3,6) 整段删掉重写，残段丢失，B 会落到 y=0，和 D 重叠。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 194.44800000000004, "end": 195.86269387755107, "text": "树的编辑有两类。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 195.86269387755107, "end": 201.8751428571429, "text": "交换两个名称：树形不变，每个模块的宽高换了位置，谁被托高要看新宽高。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 201.8751428571429, "end": 206.82657142857147, "text": "移动一个节点：它和整棵子树都要重摆，后面的轮廓也跟着变。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 206.82657142857147, "end": 211.77800000000005, "text": "这两类正是以后搜索的邻域；现在先学会判断“谁需要重摆”。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 211.77800000000002, "end": 218.87800000000001, "text": "和上一课一样，解码前先查名称：树里不能出现清单之外的模块，不能重复，也不能缺失。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 218.87800000000001, "end": 225.62300000000002, "text": "轮廓算法保证摆出来的块互不重叠，但它不管外框：5040棵树里有360棵越界。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 225.62300000000002, "end": 228.10800000000003, "text": "合法性要靠Lab2的检查器。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 228.108, "end": 242.9315294117647, "text": "本机穷举可以核对：5个节点42种形状，乘120种标号，共5040棵树；其中4680棵完整放进10×8，越界的360棵全部没有内部重叠；最小包围盒面积24，只有8棵达到。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 242.9315294117647, "end": 246.108, "text": "轮廓算法保证不重叠，但不保证面积小。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 246.108, "end": 253.78657142857142, "text": "要提醒边界：5040、4680、24只属于当前五块、固定尺寸、禁止旋转和10×8外框。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 253.78657142857142, "end": 256.2865714285714, "text": "模块清单一变，数字全部作废。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 256.2865714285714, "end": 261.10799999999995, "text": "穷举只在页面提供的小规模按钮下做，不会在后台持续运行。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 261.108, "end": 268.83, "text": "包围盒从二十七变成三十六；合法性没有告诉我们这次交换是否更好。", "delivery": "voice", "sourceKey": "score", "words": [{"text": "包围", "start": 261.210083, "end": 261.561666}, {"text": "盒", "start": 261.561666, "end": 261.717916}, {"text": "从", "start": 261.743958, "end": 261.874166}, {"text": "二十七", "start": 261.88716600000004, "end": 262.39499900000004}, {"text": "变成", "start": 262.421041, "end": 262.694499}, {"text": "三十六", "start": 262.7205, "end": 263.25437500000004}, {"text": "合法性", "start": 263.710083, "end": 264.296041}, {"text": "没有", "start": 264.322083, "end": 264.517416}, {"text": "告诉", "start": 264.530416, "end": 264.777832}, {"text": "我们", "start": 264.790833, "end": 265.155416}, {"text": "这次", "start": 265.272583, "end": 265.63716600000004}, {"text": "交换", "start": 265.650208, "end": 266.079916}, {"text": "是否", "start": 266.10591600000004, "end": 266.41841600000004}, {"text": "更", "start": 266.431458, "end": 266.61374900000004}, {"text": "好", "start": 266.61375000000004, "end": 266.874166}]}, {"start": 268.83, "end": 277.104, "text": "进入实验修改树，用轮廓线解释高度，而不是只背左孩子和右孩子。", "delivery": "voice", "sourceKey": "counterexample", "words": [{"text": "进入", "start": 268.93208300000003, "end": 269.36179100000004}, {"text": "实验", "start": 269.387833, "end": 269.72637399999996}, {"text": "修改", "start": 269.739375, "end": 270.07791599999996}, {"text": "树", "start": 270.07791599999996, "end": 270.41645700000004}, {"text": "用", "start": 270.68991600000004, "end": 270.89824899999996}, {"text": "轮廓线", "start": 270.91125, "end": 271.54929100000004}, {"text": "解释", "start": 271.575333, "end": 271.848791}, {"text": "高度", "start": 271.86179100000004, "end": 272.239416}, {"text": "而", "start": 272.61699999999996, "end": 272.81229099999996}, {"text": "不是", "start": 272.81229099999996, "end": 273.059707}, {"text": "只", "start": 273.08574999999996, "end": 273.24199999999996}, {"text": "背", "start": 273.24199999999996, "end": 273.450333}, {"text": "左", "start": 273.47637499999996, "end": 273.645625}, {"text": "孩子", "start": 273.645625, "end": 274.17949999999996}, {"text": "和", "start": 274.29666599999996, "end": 274.465957}, {"text": "右孩子", "start": 274.47895800000003, "end": 275.129999}]}], "cuts": [{"scene": "convention", "sourceKey": "recipe", "sourceStart": 0.0, "sourceEnd": 7.05, "start": 56.17, "end": 63.22}, {"scene": "preorder", "sourceKey": "root", "sourceStart": 7.05, "sourceEnd": 13.188, "start": 63.22, "end": 69.358}, {"scene": "golden-walk", "sourceKey": "walk", "sourceStart": 13.188, "sourceEnd": 21.75, "start": 89.528, "end": 98.09}, {"scene": "d-landing", "sourceKey": "D", "sourceStart": 21.75, "sourceEnd": 29.76, "start": 98.09, "end": 106.10000000000001}, {"scene": "swap-predict", "sourceKey": "predict", "sourceStart": 29.76, "sourceEnd": 36.476, "start": 123.10000000000001, "end": 129.816}, {"scene": "lift-result", "sourceKey": "lift", "sourceStart": 36.476, "sourceEnd": 44.438, "start": 129.816, "end": 137.77800000000002}, {"scene": "score-compare", "sourceKey": "score", "sourceStart": 44.438, "sourceEnd": 52.16, "start": 261.108, "end": 268.83}, {"scene": "transfer", "sourceKey": "counterexample", "sourceStart": 52.16, "sourceEnd": 60.434, "start": 268.83, "end": 277.104}], "newSpeech": false, "audioSha256": "d4402f78a08c8b7ae4ec6b2f63063ccfb468beb71532d0e3b232e0f3ff35496b", "sourceHashes": {"content/interactive05.mjs": "af3d9b5f193cd7ce43bfff4f8c2254c8d9f96f525d555ba05307e7434743bdbe", "dist/media/05/zh.m4a": "5ec2c9b60197bb90a75eef71d553b7f22639caa8672193027efe53b2dc53e68a", "dist/media/05/zh.json": "a039180e3e83033710ce4de345024773814e08e4e330ce75894663db2fd0c95f", "dist/assets/bstar05.mjs": "ed37aa21390213e86fa1febfaa95a4a60ea085473e1ffd25e39f91c730db19fe"}};
